pub const PAGE: &str = r##"<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>导入 AI 对话 · 妥啦</title>
<style>body{margin:0;background:linear-gradient(135deg,#f7f4f5,#eaf1ff);color:#30394d;font:16px/1.7 system-ui,sans-serif}main{max-width:840px;margin:48px auto;padding:24px}h1{font-size:32px;margin-bottom:4px}p{color:#748097}.card{padding:28px;background:#ffffffdc;border:1px solid white;border-radius:28px;margin:20px 0}input,select,button{font:inherit;border:1px solid #dee4ef;border-radius:14px;padding:12px;box-sizing:border-box}input{max-width:100%}button{background:#4269c7;color:white;cursor:pointer}button.secondary{background:#eef3ff;color:#4269c7}button:disabled{opacity:.5;cursor:wait}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.muted{font-size:14px;color:#748097}label{display:block;margin:12px 0}#notice{white-space:pre-wrap;color:#4269c7}article{border-top:1px solid #e9edf5;padding:16px 0}pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere}[hidden]{display:none!important}</style>
<main><span>妥啦 · 让过去的对话接着帮你</span><h1>导入其他 AI 对话</h1><p>支持 ChatGPT、Claude、DeepSeek 的官方 ZIP / JSON 导出文件。</p>
<section id="login" class="card"><h2>登录妥啦账号</h2><p>与手机使用同一个账号。登录凭据只用于妥啦服务，不需要其他 AI 平台的密码。</p><form id="loginForm"><label>手机号<input id="phone" type="tel" autocomplete="username" required pattern="1[0-9]{10}"></label><label>密码<input id="password" type="password" autocomplete="current-password" required></label><button>登录</button></form></section>
<section id="import" class="card" hidden><div class="row"><h2>选择导出文件</h2><button id="logout" class="secondary">退出</button></div><label>来源<select id="provider"><option value="chatgpt">ChatGPT</option><option value="claude">Claude</option><option value="deepseek">DeepSeek</option></select></label><p id="guide"></p><input id="file" type="file" accept=".zip,.json,application/json,application/zip"><p class="muted">单文件最多 25 MB。ZIP 无需解压；大包可解压后分批选择 conversations*.json。原始压缩包不长期保存。文件上传后先预览，确认后才供助手检索；长期记忆另行确认。</p><button id="upload">上传并预览</button><p class="muted">下载链接可能需要原平台登录。请先在原平台下载文件，再在这里选择；这页不会获取你的其他平台登录凭据。</p></section>
<section id="preview" class="card" hidden><h2>确认导入范围</h2><p id="summary"></p><p id="warnings" class="muted"></p><div class="row"><button id="commit">确认导入全部</button><button id="cancel" class="secondary">取消并删除预览</button></div><div id="items"></div><button id="more" class="secondary" hidden>查看更多</button></section><p id="notice" role="status"></p><p class="muted">导入完成后，在手机「能力 → 导入 AI 对话」中查看、搜索或删除。此页刷新后需要重新登录；待确认预览在一小时后自动清理。</p></main>
<script>
(()=>{'use strict';let token='',batch=null,offset=0;const $=id=>document.getElementById(id);const guides={chatgpt:'ChatGPT：设置 → 数据控制 → 导出数据，下载导出 ZIP。',claude:'Claude 网页版或桌面端：Settings → Privacy → Export data，下载邮件里的导出文件。',deepseek:'DeepSeek：头像 → 设置 → 数据管理 → 导出所有历史对话。'};function guide(){$('guide').textContent=guides[$('provider').value]}guide();$('provider').onchange=guide;function notice(s){$('notice').textContent=s}async function request(path,method='GET',body){const multipart=body instanceof FormData;const response=await fetch('/v1'+path,{method,headers:{Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(body&&!multipart?{'Content-Type':'application/json'}:{})},...(body?{body:multipart?body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('服务未返回有效数据，请检查文件大小或稍后重试')}if(!response.ok)throw Error(data.error?.message||'操作失败');return data}async function run(fn){document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){notice(e.message)}finally{document.querySelectorAll('button').forEach(b=>b.disabled=false)}}function render(data,append=false){if(!append){$('items').replaceChildren();offset=0}$('preview').hidden=false;$('summary').textContent=`${data.conversation_count} 段对话 · ${data.message_count} 条文字消息；忽略 ${data.skipped_conversations} 段空白或重复对话、${data.skipped_blocks} 个非正文内容块。`;$('warnings').textContent=data.warnings.join(' ');for(const item of data.items){const article=document.createElement('article');const title=document.createElement('strong');title.textContent=item.title;const text=document.createElement('p');text.textContent=item.message_count+' 条消息 · '+item.preview;article.append(title,text);for(const warning of item.warnings){const w=document.createElement('p');w.className='muted';w.textContent=warning;article.append(w)}$('items').append(article)}offset+=data.items.length;$('more').hidden=!data.has_more}
$('loginForm').onsubmit=e=>{e.preventDefault();run(async()=>{const data=await request('/auth/phone/login','POST',{phone:$('phone').value.trim(),password:$('password').value});token=data.token;$('password').value='';$('login').hidden=true;$('import').hidden=false;notice('已登录，可以选择导出文件。')})};$('logout').onclick=()=>run(async()=>{if(batch)await request('/ai-history/previews/'+batch,'DELETE');await request('/auth/logout','POST',{});token='';batch=null;$('login').hidden=false;$('import').hidden=true;$('preview').hidden=true;notice('已退出。')});$('upload').onclick=()=>run(async()=>{if(batch)throw Error('请先确认或取消当前预览');const file=$('file').files[0];if(!file)throw Error('请先选择文件');if(file.size>25*1024*1024)throw Error('文件超过 25 MB，请解压后分批选择对话 JSON');notice('正在上传和解析…');const form=new FormData();form.append('file',file);const data=await request('/ai-history/'+$('provider').value+'/preview','POST',form);batch=data.id;render(data);notice('已解析，请检查预览后确认。')});$('more').onclick=()=>run(async()=>render(await request('/ai-history/previews/'+batch+'?offset='+offset),true));$('cancel').onclick=()=>run(async()=>{await request('/ai-history/previews/'+batch,'DELETE');batch=null;$('preview').hidden=true;notice('已取消并删除预览。')});$('commit').onclick=()=>run(async()=>{notice('正在导入…');const data=await request('/ai-history/previews/'+batch+'/commit','POST',{all:true});batch=null;$('preview').hidden=true;$('file').value='';notice(`导入完成：新增 ${data.imported} 段，更新 ${data.updated} 段，跳过 ${data.skipped} 段相同记录。可在手机查看。`)});
})();</script></html>"##;
